properties.query:
let windowSize = 2h;

// S58: Archive Supply-Chain (Zip Slip)
let S58 =
    UAVArchiveExtract_CL
    | where TimeGenerated > ago(windowSize)
    | where ZipSlipDetected == true
    | extend Stage = 'S58', Operator = tostring(Operator)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

// S54: Webshell Upload
let S54 =
    UAVWebAccess_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'webshell_upload'
    | extend Stage = 'S54', Operator = tostring(Operator)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

// S92: Exfil (SAR/Auth)
let S92 =
    UAVExfilFlow_CL
    | where TimeGenerated > ago(windowSize)
    | where DataClass in ('sar_imagery','auth_token')
    | extend Stage = 'S92', Operator = tostring(Operator)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

union S58, S54, S92
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by Operator
| where StageCount >= 2
| extend CampaignType = "C17_아카이브전달_웹셸_SAR유출"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, Operator, StagesSeen, StageCount, CampaignType, StepSummary, Severity
